import {seedRecipes} from './data.js';
import {ingredientImage,dishImage} from './ingredient-icons.js';
import {canonical,displayAmount,ingredientStatus,matchRecipe,sortRecipes,shoppingText} from './core.js';

const KEY='wokzy.personal.v1';
const emptyState=()=>({pantry:[],recipes:structuredClone(seedRecipes),favorites:[],notes:[],cook:null,feedback:[]});
let state;
try {const stored=JSON.parse(localStorage.getItem(KEY)||'null');state=stored&&Array.isArray(stored.recipes)&&Array.isArray(stored.pantry)?{...emptyState(),...stored}:emptyState();} catch {state=emptyState();}
let page=['home','pantry','library','favorites'].includes(location.hash.slice(1))?location.hash.slice(1):'home';
let query='',filter='all',order='match',activeId=null,servings=2,modalKind='',returnFocus=null,saveWarned=false;
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const attr=esc;
const icon=(name,size=20)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${({home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-8H9v8H4a1 1 0 0 1-1-1Z"/>',pantry:'<rect x="5" y="3" width="14" height="18" rx="2"/><path d="M5 11h14M9 6v2m0 7v2"/>',book:'<path d="M12 5v16m0-16C9 2 3 3 3 3v16s6-1 9 2c3-3 9-2 9-2V3s-6-1-9 2Z"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0l-1 1-1-1a5.5 5.5 0 1 0-7.8 7.8L12 21l7.8-8.6a5.5 5.5 0 0 0 1-7.8Z"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',check:'<path d="m5 12 4 4L19 6"/>',leaf:'<path d="M20 4C8 2 2 9 6 17c8 4 15-2 14-13Z"/><path d="M4 20 15 9"/>',person:'<circle cx="12" cy="7" r="3"/><path d="M5 21v-2a7 7 0 0 1 14 0v2"/>',edit:'<path d="m15 5 4 4M4 20l5-1L21 7a3 3 0 0 0-4-4L5 15Z"/>',copy:'<rect x="8" y="8" width="12" height="13" rx="2"/><path d="M16 8V3H3v13h5"/>',back:'<path d="M19 12H5m6-6-6 6 6 6"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v.1"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',trash:'<path d="M3 6h18M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7m4-7v7"/>',play:'<path d="m9 5 11 7-11 7Z"/>',chat:'<path d="M21 11a8 8 0 0 1-8 8H7l-5 3 2-6a9 9 0 1 1 17-5Z"/>'})[name]||''}</svg>`;
const recipe=id=>state.recipes.find(r=>r.id===id);
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),3200);}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));return true;}catch{if(!saveWarned){toast('浏览器未能保存数据，请先导出备份。');saveWarned=true;}return false;}}
function navButton(id,label,ico){return `<button class="nav-item ${page===id?'active':''}" data-action="nav" data-page="${id}" ${page===id?'aria-current="page"':''}>${icon(ico)}<span>${label}</span>${id==='favorites'&&state.favorites.length?`<small>${state.favorites.length}</small>`:''}</button>`;}
function render(){
 const titles={home:'今天吃点好的',pantry:'打开你的食材小仓库',library:'把喜欢的味道留下来',favorites:'常吃的，也是喜欢的'};
 const eyebrow={home:'你的日常厨房',pantry:'我的食材',library:'我的菜谱库',favorites:'我的收藏'};
 $('#app').innerHTML=`<aside class="sidebar"><a class="brand" href="#home"><img src="assets/icon.svg" alt=""/><div>wokzy<span>一镬熟</span></div></a><div class="sidebar-label">一餐一饭，好好生活</div><nav aria-label="主导航">${navButton('home','今天做什么','home')}${navButton('pantry','我的食材','pantry')}${navButton('library','菜谱库','book')}${navButton('favorites','我的收藏','heart')}</nav><div class="sidebar-bottom"><div class="kitchen-note">${icon('leaf',26)}<p>不用准备全世界，<br>手边的食材就很好。</p><span>YOUR LITTLE KITCHEN</span></div><button class="subtle" data-action="about">${icon('info',16)} 关于体验版 <span>DEMO</span></button><button class="profile" data-action="feedback"><div class="avatar">W</div><div>我的小厨房<small>记录一餐，也记录灵感</small></div>${icon('chat',17)}</button></div></aside>
 <main class="main"><header class="topbar"><div class="breadcrumb">我的小厨房 <span>/</span> ${eyebrow[page]}</div><div class="top-actions"><span class="season">${icon('leaf',15)} 好好吃饭，慢慢生活</span><button class="button primary small" data-action="new-recipe">${icon('plus',17)} 记录菜谱</button></div></header><div class="content"><div class="page-heading"><div><div class="eyebrow">${eyebrow[page]} <span>· WOKZY</span></div><h1>${titles[page]}<span class="title-dot">.</span></h1></div><div class="heading-meta">${page==='home'?'今天的好心情，从这一餐开始。':page==='pantry'?'知道手边有什么，做饭就容易一点。':'每一道菜，都可以有你的做法。'}</div></div>
 ${page==='home'?homeView():page==='pantry'?pantryView():libraryView()}
 <footer class="footer"><span>wokzy 一镬熟 <span class="footer-sep">/</span> 好好做饭，好好吃饭。</span><button data-action="about">关于体验版 · 数据备份</button><button data-action="feedback">体验有想法？记下来 ${icon('arrow',14)}</button></footer></div></main><nav class="mobile-nav" aria-label="手机导航">${navButton('home','今天','home')}${navButton('pantry','食材','pantry')}${navButton('library','菜谱','book')}${navButton('favorites','收藏','heart')}</nav>`;
 renderCards();
}
function pantryChips(limit=8){return state.pantry.slice(0,limit).map(p=>`<button class="ingredient-chip" data-action="edit-stock" data-name="${attr(p.name)}"><span>${ingredientImage(p.name)}</span>${esc(p.name)}${p.qty?`<small>${esc(p.qty)}${esc(p.unit)}</small>`:''}</button>`).join('');}
function homeView(){const count=state.recipes.filter(r=>matchRecipe(r,state.pantry).ready).length;return `<section class="hero"><div class="hero-copy"><span class="hero-label"><span></span> SMALL INGREDIENTS, BIG POSSIBILITIES</span><h2>有什么，<br>就做什么<span>。</span></h2><p>打开冰箱里的可能，<br>用手边的食材，做一餐喜欢的饭。</p><button class="button dark" data-action="focus-pantry">${icon('spark',17)} 从我的食材开始 ${icon('arrow',17)}</button></div><div class="hero-art brush-hero" aria-hidden="true"><div class="sketch-circle"></div><div class="hero-tomato">${ingredientImage('番茄')}</div><div class="hero-egg">${ingredientImage('鸡蛋')}</div><div class="hero-greens">${ingredientImage('西兰花')}</div><span class="brush-spark">✳</span><div class="hero-stamp">手边这几样<span>就是一餐好滋味</span><small>A LITTLE EVERYDAY JOY</small></div></div></section>
 ${state.cook&&recipe(state.cook.recipeId)?`<button class="resume-banner" data-action="resume"><span>${icon('play',18)} 上次的 ${esc(recipe(state.cook.recipeId).name)}，做到第 ${state.cook.step+1} 步</span><b>继续做菜 ${icon('arrow',16)}</b></button>`:''}
 <section class="pantry-strip" id="pantry-entry"><div class="section-line"><h2>${icon('pantry',20)} 我的现有食材 <span class="count-badge">${state.pantry.length}</span></h2><button class="text-button" data-action="nav" data-page="pantry">管理食材 ${icon('arrow',15)}</button></div><div class="pantry-flex">${state.pantry.length?pantryChips(7):`<span class="empty-pantry">冰箱里有什么？先添加几样，让灵感来找你。</span>`}<form id="quick-pantry" class="quick-add"><input name="name" aria-label="添加现有食材" placeholder="输入食材，回车添加" autocomplete="off" required maxlength="30"><button aria-label="添加食材">${icon('plus',18)}</button></form></div><div class="pantry-hint">${state.pantry.length?`${icon('info',13)} 只匹配已添加的食材和调料，未填数量时会提示确认。 <span class="ready-hint">${count} 道食材已列齐</span>`:`<span>想先感受一下？</span><button data-action="demo">填入示例食材 ${icon('arrow',13)}</button><span class="hint-light">番茄、鸡蛋、西兰花、蒜、盐、食用油</span>`}</div></section>
 <section class="recommendations"><div class="section-line recommendation-heading"><div><div class="tiny-label">COOK WITH WHAT YOU HAVE</div><h2>今天，可以这样吃 <span id="recipe-count" class="plain-count"></span></h2></div><label class="sort-label">排序 <select id="sort-select" aria-label="菜谱排序"><option value="match" ${order==='match'?'selected':''}>食材匹配优先</option><option value="time" ${order==='time'?'selected':''}>耗时最短优先</option></select></label></div>${recipeToolbar()}<div id="recipe-grid" class="recipe-grid"></div></section>`;}
function recipeToolbar(){return `<div class="recipe-toolbar"><div class="tabs" role="group" aria-label="筛选菜谱">${[['all','全部灵感'],['ready','食材已列齐'],['few','最多缺两样']].map(([id,name])=>`<button data-action="filter" data-filter="${id}" class="${filter===id?'selected':''}" aria-pressed="${filter===id}">${name}</button>`).join('')}</div><label class="search">${icon('search',17)}<input id="recipe-search" value="${attr(query)}" placeholder="搜索菜名、食材或标签" aria-label="搜索菜谱"></label></div>`;}
function libraryView(){return `<section class="library-banner"><div>${icon('book',29)}<h2>${page==='favorites'?'喜欢的味道，随时再做':'让每一次好吃，都有迹可循'}</h2><p>从一道家常菜开始，慢慢攒下属于你的拿手菜。</p></div><button class="button outline" data-action="new-recipe">${icon('plus',17)} 新建我的菜谱</button></section><div class="section-line library-heading"><h2>${page==='favorites'?'我的收藏':'全部菜谱'} <span id="recipe-count" class="plain-count"></span></h2><button class="text-button" data-action="reference">整理网上的做法 ${icon('arrow',15)}</button></div>${recipeToolbar()}<div id="recipe-grid" class="recipe-grid"></div>`;}
function pantryView(){const staples=['盐','食用油','生抽','白糖','香油','淀粉','豆瓣酱','花椒粉'];return `<section class="pantry-page-banner"><div><span class="tiny-label">A LITTLE PANTRY, A LOT OF POSSIBILITIES</span><h2>从手边这几样开始。</h2><p>数量可以稍后补充，先把已有食材记下来。</p></div><div class="pantry-illustrations" aria-hidden="true">${ingredientImage('西兰花')}${ingredientImage('鸡蛋')}${ingredientImage('番茄')}</div></section><section class="stock-section"><div class="section-line"><h2>食材小仓库 <span class="count-badge">${state.pantry.filter(p=>!p.staple).length}</span></h2><button class="button dark small" data-action="add-stock">${icon('plus',16)} 添加食材</button></div>${state.pantry.some(p=>!p.staple)?`<div class="stock-grid">${state.pantry.filter(p=>!p.staple).map(p=>`<button class="stock-card" data-action="edit-stock" data-name="${attr(p.name)}"><span class="stock-icon">${ingredientImage(p.name)}</span><div><b>${esc(p.name)}</b><small>${p.qty?esc(p.qty)+esc(p.unit):'数量未填写'}</small></div>${icon('edit',16)}</button>`).join('')}</div>`:`<div class="empty-state compact"><div class="empty-art">${ingredientImage('胡萝卜')}</div><h3>小仓库等你来填满</h3><p>添加食材后，推荐会跟着发生变化。</p><button class="button outline small" data-action="demo">先试试示例食材</button></div>`}</section><section class="stock-section"><div class="section-line"><div><h2>常备调料</h2><p class="section-description">点选你确认已有的调料，推荐时就会计入。</p></div><button class="text-button" data-action="add-staple">添加其他调料 ${icon('plus',15)}</button></div><div class="staple-grid">${[...new Set([...staples,...state.pantry.filter(p=>p.staple).map(p=>p.name)])].map(name=>{const p=state.pantry.find(p=>canonical(p.name)===name);return `<div class="staple-item ${p?'owned':''}"><button data-action="toggle-staple" data-name="${attr(name)}" aria-pressed="${!!p}"><span class="checkbox">${p?icon('check',13):''}</span>${ingredientImage(name)}${esc(name)}</button>${p?`<button class="staple-amount" data-action="edit-stock" data-name="${attr(name)}" aria-label="编辑${attr(name)}用量">${p.qty?`${esc(p.qty)}${esc(p.unit)}`:'补充数量'}</button>`:''}</div>`}).join('')}</div></section><div class="soft-note">${icon('info',18)}<span>食材数量不会在做完菜后自动扣减。你可以随时点开食材，调整数量或移除。</span></div><button class="button primary pantry-recommend" data-action="nav" data-page="home">看看这些食材能做什么 ${icon('arrow',18)}</button>`;}
function filteredRecipes(){let list=page==='favorites'?state.recipes.filter(r=>state.favorites.includes(r.id)):state.recipes;const q=canonical(query.trim()).toLowerCase();if(q)list=list.filter(r=>[r.name,...r.tags,...r.ingredients.map(i=>canonical(i.name))].some(t=>t.toLowerCase().includes(q)));list=list.filter(r=>{const m=matchRecipe(r,state.pantry);return filter==='ready'?m.ready:filter==='few'?m.missing.length+m.short.length<=2:true;});return order==='time'?[...list].sort((a,b)=>a.minutes-b.minutes):sortRecipes(list,state.pantry);}
function renderCards(){const grid=$('#recipe-grid');if(!grid)return;const list=filteredRecipes();$('#recipe-count').textContent=`${list.length} 道`;grid.innerHTML=list.length?list.map(card).join(''):`<div class="empty-state"><div class="empty-art">${page==='favorites'?icon('heart',40):'<img class="ingredient-icon" src="assets/brush-ingredients/plate.png" alt="" aria-hidden="true" width="24" height="24">'}</div><h3>${page==='favorites'&&!state.favorites.length?'把喜欢的菜先收藏起来':'还没有符合条件的菜谱'}</h3><p>${page==='favorites'&&!state.favorites.length?'点一下菜谱上的爱心，下次更容易找到。':'试着换个关键词、放宽筛选，或记录一道自己的菜。'}</p><button class="button outline small" data-action="${page==='favorites'?'browse':'reset-filters'}">${page==='favorites'?'去菜谱库看看':'查看全部菜谱'}</button></div>`;}
function recipeArt(r){const items=(r.ingredients||[]).filter(i=>i.category!=='调料').slice(0,3);return `<div class="recipe-art" aria-hidden="true">${items.map(i=>ingredientImage(i.name)).join('')}</div>`;}
function card(r){const m=matchRecipe(r,state.pantry);const n=m.missing.length+m.short.length;let status=m.ready?`${icon('check',13)} 食材已列齐`:`还需准备 ${n} 样`;return `<article class="recipe-card"><div class="card-image"><button class="image-open" data-action="detail" data-id="${attr(r.id)}" aria-label="查看${attr(r.name)}">${recipeArt(r)}</button><span class="card-category">${esc(r.tag||'我的私房菜')}</span><button class="favorite ${state.favorites.includes(r.id)?'is-favorite':''}" data-action="favorite" data-id="${attr(r.id)}" aria-label="${state.favorites.includes(r.id)?'取消收藏':'收藏'}${attr(r.name)}" aria-pressed="${state.favorites.includes(r.id)}">${icon('heart',18)}</button></div><button class="card-info" data-action="detail" data-id="${attr(r.id)}"><h3>${esc(r.name)}</h3><p>${esc(r.subtitle||'把自己的做法，记成一份好吃的菜谱。')}</p><div class="card-meta"><span>${icon('clock',14)} ${r.minutes} 分钟</span><span>${icon('person',14)} ${r.servings} 人份</span><span class="difficulty">${esc(r.difficulty||'简单')}</span></div><div class="match-row"><span class="match-badge ${m.ready?'ready':''}">${status}</span><span class="match-summary">${m.ready?(m.unknown.length?'用量待确认':'可以开火了'):esc([...m.missing,...m.short].slice(0,2).map(i=>i.name).join('、'))+(n>2?'…':'')}</span>${icon('arrow',16)}</div></button></article>`;}

function showModal(html,kind,wide=false){if(!modalKind)returnFocus=document.activeElement;modalKind=kind;$('#overlay').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${({detail:'菜谱详情',stock:'食材信息',editor:'编辑菜谱',cook:'烹饪模式',feedback:'体验反馈',about:'关于体验版',copy:'待准备清单'})[kind]||'提示'}" tabindex="-1">${html}</section></div>`;document.body.classList.add('modal-open');$('#app').inert=true;requestAnimationFrame(()=>{$('.modal').focus({preventScroll:true});});}
const closeButton=()=>`<button class="icon-button modal-close" data-action="close" aria-label="关闭">${icon('close')}</button>`;
function closeModal(){modalKind='';$('#overlay').innerHTML='';document.body.classList.remove('modal-open');$('#app').inert=false;returnFocus?.isConnected&&returnFocus.focus({preventScroll:true});}
function detail(id,keepServings=false){const r=recipe(id);if(!r)return;activeId=id;if(!keepServings)servings=r.servings;const m=matchRecipe(r,state.pantry,servings);const notes=state.notes.filter(n=>n.recipeId===id);const saved=r.sourceType==='示例菜谱'?'Wokzy 家常菜示例 · 做法可按喜好调整':r.sourceType||'原创';showModal(`${closeButton()}<div class="detail-cover">${recipeArt(r)}<div><span>${esc(r.tag||'我的私房菜')}</span><h2>${esc(r.name)}</h2><p>${esc(r.subtitle)}</p></div></div><div class="detail-body"><div class="detail-metadata"><span>${icon('clock',16)} ${r.minutes} 分钟</span><span>${icon('person',16)} ${r.servings} 人份起</span><span>${esc(r.difficulty)}</span><span>${esc(r.tools||'家用厨具')}</span></div><div class="detail-actions"><button class="button outline small" data-action="favorite" data-id="${attr(id)}">${icon('heart',16)} ${state.favorites.includes(id)?'已收藏':'收藏菜谱'}</button><button class="button outline small" data-action="edit-recipe" data-id="${attr(id)}">${icon('edit',16)} 编辑做法</button></div><div class="section-line ingredient-heading"><div><h3>先准备这些</h3><p>用量按人数调整，火候与时间仍需看状态。</p></div><div class="serving-control"><button data-action="serving-minus" aria-label="减少一人份" ${servings<=1?'disabled':''}>−</button><b>${servings} 人份</b><button data-action="serving-plus" aria-label="增加一人份" ${servings>=20?'disabled':''}>+</button></div></div><div class="ingredient-legend">点选左侧圆圈，标记食材已有或移除已有状态。</div><div class="ingredient-list">${m.items.map((i,index)=>`<div class="ingredient-row"><button class="ingredient-check ${['enough','unknown','short'].includes(i.status.kind)?'checked':''}" data-action="ingredient-toggle" data-index="${index}" aria-label="${state.pantry.some(p=>canonical(p.name)===canonical(i.name))?'移除已有状态':'标记已有'}${attr(i.name)}">${['enough','unknown','short'].includes(i.status.kind)?icon('check',13):''}</button>${ingredientImage(i.name)}<span class="ingredient-name">${esc(i.name)} ${i.optional?'<small>可选</small>':''}<small class="ingredient-category">${esc(i.category)}</small></span><b>${esc(displayAmount(i,servings,r.servings))}</b><span class="status ${i.status.kind}">${i.status.label}</span></div>`).join('')}</div><button class="text-button copy-shopping" data-action="copy-shopping">${icon('copy',15)} 复制缺料清单</button><div class="section-line steps-title"><h3>这样做，一步一步来</h3><span>${r.steps.length} 个步骤</span></div><ol class="detail-steps">${r.steps.map((s,index)=>`<li><span>${String(index+1).padStart(2,'0')}</span><div><h4>${esc(s.title)}</h4><p>${esc(s.text)}</p>${s.tip?`<small>小提示：${esc(s.tip)}</small>`:''}</div></li>`).join('')}</ol><div class="source-note">${icon('book',16)}<div>${esc(saved)}${safeUrl(r.sourceUrl)?` · <a href="${attr(r.sourceUrl)}" target="_blank" rel="noopener noreferrer">查看参考来源 ↗</a>`:''}${r.originalSourceType?'<span>已保存个人整理版本，保留原来源信息。</span>':''}${r.photoSource?`<span>成品图仅作展示参考 · <a href="${attr(r.photoSource)}" target="_blank" rel="noopener noreferrer">${esc(r.photoCredit)} ↗</a>；示例步骤由 Wokzy 整理。</span>`:''}</div></div><section class="notes-section"><h3>留一点自己的心得 <span>${notes.length}</span></h3>${notes.map(n=>`<div class="note"><small>${esc(new Date(n.date).toLocaleDateString('zh-CN'))}</small><p>${esc(n.text)}</p></div>`).join('')}<form id="note-form"><textarea name="note" placeholder="比如：下次番茄多焖一会儿，汤汁拌饭更好吃……" aria-label="做菜心得" required maxlength="3000"></textarea><button class="button outline small">保存心得</button></form></section></div><div class="modal-sticky"><div><b>${m.ready?'食材种类已列齐':`还有 ${m.missing.length+m.short.length} 样需要准备`}</b><small>${m.unknown.length?'部分食材用量待确认，开火前再检查一下。':'备好食材后，就可以开始了。'}</small></div><button class="button primary" data-action="start-cook">${icon('play',17)} ${state.cook?.recipeId===id?'继续 / 开始做菜':'开始做菜'}</button></div>`,'detail',true);}
function safeUrl(value){try{return ['https:','http:'].includes(new URL(value).protocol);}catch{return false;}}
function stockDialog(name='',staple=false){const stock=state.pantry.find(p=>p.name===name);showModal(`${closeButton()}<div class="modal-header"><span class="tiny-label">MY LITTLE PANTRY</span><h2>${stock?'更新这份食材':'添加一点新鲜'}</h2><p>先记住你有什么，数量可以稍后再填。</p></div><form id="stock-form" data-original="${attr(name)}" class="padded-form"><label>食材名称<input name="name" value="${attr(name)}" placeholder="例如：番茄" required maxlength="30"></label><div class="two-fields"><label>现有数量 <span>选填</span><input name="qty" type="number" min="0.01" step="any" value="${attr(stock?.qty||'')}" placeholder="例如：2"></label><label>单位 <span>填数量时必选</span><select name="unit">${['','个','克','千克','毫升','升','根','瓣','片','朵','块','包','勺','碗'].map(u=>`<option value="${u}" ${stock?.unit===u?'selected':''}>${u||'选择单位'}</option>`).join('')}</select></label></div><label class="checkbox-label"><input type="checkbox" name="staple" ${stock?.staple||staple?'checked':''}> 这是常备调料</label><div class="form-footer">${stock?`<button type="button" class="text-button danger" data-action="remove-stock" data-name="${attr(name)}">${icon('trash',16)} 移除食材</button>`:'<span></span>'}<button class="button primary">${icon('check',16)} 保存食材</button></div></form>`,'stock');setTimeout(()=>$('.modal input')?.focus(),80);}

function editorRow(i={name:'',qty:null,unit:'',category:'主料',optional:false,amount:'适量'}){return `<div class="editor-ingredient"><input data-field="name" aria-label="食材名称" placeholder="食材名称" value="${attr(i.name)}" maxlength="30" required><input data-field="amount" aria-label="用量" placeholder="如 2 或 适量" value="${attr(i.qty!==null&&i.qty!==undefined&&i.qty!==''?i.qty:i.amount||'')}" required><input data-field="unit" aria-label="单位" placeholder="个 / 克" value="${attr(i.unit)}" maxlength="10"><select data-field="category" aria-label="食材分类">${['主料','辅料','调料'].map(c=>`<option ${i.category===c?'selected':''}>${c}</option>`).join('')}</select><label class="optional-check"><input type="checkbox" data-field="optional" ${i.optional?'checked':''}>可选</label><button type="button" class="icon-button" data-action="remove-row" aria-label="移除此行食材">${icon('close',16)}</button></div>`;}
function editor(id=null,reference=false){const r=id?recipe(id):null;showModal(`${closeButton()}<div class="modal-header"><span class="tiny-label">A RECIPE OF YOUR OWN</span><h2>${r?'把这道菜，做成自己的版本':reference?'把网上的做法整理下来':'记下一道拿手菜'}</h2><p>不用写得很专业，记得下次能照着做好就行。</p></div><form id="recipe-form" class="padded-form" data-id="${attr(id||'')}"><label>菜谱名称<input name="name" placeholder="给这道菜起个名字" value="${attr(r?.name||'')}" required maxlength="60"></label><label>一句话描述 <span>选填</span><input name="subtitle" placeholder="这道菜，有什么让你喜欢的地方？" value="${attr(r?.subtitle||'')}" maxlength="120"></label><div class="three-fields"><label>默认人数<input name="servings" type="number" min="1" max="20" required value="${r?.servings||2}"></label><label>总耗时 / 分钟<input name="minutes" type="number" min="1" max="1440" required value="${r?.minutes||20}"></label><label>难度<select name="difficulty">${['简单','适中','有挑战'].map(d=>`<option ${r?.difficulty===d?'selected':''}>${d}</option>`).join('')}</select></label></div><div class="two-fields"><label>需要的器具 <span>选填</span><input name="tools" placeholder="例如：炒锅" value="${attr(r?.tools||'')}" maxlength="60"></label><label>标签 <span>用逗号分隔</span><input name="tags" placeholder="例如：家常菜，快手菜" value="${attr(r?.tags?.join('，')||'')}" maxlength="120"></label></div><div class="form-section-heading"><h3>要准备的食材</h3><button class="text-button" type="button" data-action="add-row">${icon('plus',15)} 添加一行</button></div><p class="field-hint">用量可填数字或“适量”；数字用量会随人数调整。</p><div class="editor-ingredients">${(r?.ingredients||[{name:'',qty:null,amount:'',category:'主料',unit:''},{name:'',qty:null,amount:'',category:'调料',unit:''}]).map(editorRow).join('')}</div><label class="steps-label">烹饪步骤 <span>每行一个步骤</span><textarea name="steps" rows="7" placeholder="先洗净、切好食材。&#10;热锅倒油，放入食材翻炒。&#10;调味后出锅。" required maxlength="20000">${esc(r?.steps.map(s=>`${s.title}：${s.text}${s.tip?'（小提示：'+s.tip+'）':''}`).join('\n')||'')}</textarea></label><div class="two-fields"><label>内容来源<select name="sourceType">${['原创','参考网络整理'].map(t=>`<option ${t===(r?.sourceType?.includes('原创')?'原创':r?'参考网络整理':reference?'参考网络整理':'原创')?'selected':''}>${t}</option>`).join('')}</select></label><label>参考链接 <span>选填</span><input name="sourceUrl" type="url" placeholder="https://…" value="${attr(r?.sourceUrl||'')}"></label></div>${reference?'<div class="soft-note">可先把参考文字粘贴到步骤中，再手动整理。网页和 Bilibili 自动提取计划后续加入。</div>':''}<div class="form-footer"><button type="button" class="text-button" data-action="${r?'back-detail':'close'}">取消</button><button class="button primary">${icon('check',17)} 保存菜谱</button></div></form>`,'editor',true);}

function startCook(){const r=recipe(activeId);if(!r)return;if(state.cook?.recipeId===activeId&&state.cook.servings===servings){showCook();return;}state.cook={recipeId:activeId,servings,step:0,done:[]};save();showCook();render();}
function showCook(){const c=state.cook,r=recipe(c?.recipeId);if(!r)return;activeId=r.id;servings=c.servings;c.step=Math.min(c.step,r.steps.length-1);const step=r.steps[c.step];const done=c.done.includes(c.step);showModal(`${closeButton()}<div class="cook-header"><button class="text-button" data-action="back-detail">${icon('back',16)} 返回菜谱</button><span>COOKING WITH WOKZY</span></div><div class="cook-title"><span>${dishImage(r)}</span><div><h2>${esc(r.name)}</h2><p>${c.servings} 人份 · ${r.steps.length} 个步骤 · 进度自动保存</p></div></div><div class="cook-layout"><aside class="cook-ingredients"><h3>食材随手查</h3>${r.ingredients.map(i=>`<div><span>${ingredientImage(i.name)}${esc(i.name)}${i.optional?'<small>可选</small>':''}</span><b>${esc(displayAmount(i,c.servings,r.servings))}</b></div>`).join('')}<p>人数已调整，步骤时间与火候<br>仍以食材的实际状态为准。</p></aside><div class="cook-main"><div class="cook-progress-label"><span>STEP ${String(c.step+1).padStart(2,'0')}</span><small>${c.step+1} / ${r.steps.length}</small></div><div class="cook-progress"><span style="width:${(c.step+1)/r.steps.length*100}%"></span></div><h3>${esc(step.title)}</h3><p class="cook-instruction">${esc(step.text)}</p>${step.tip?`<div class="cook-tip">${icon('leaf',19)}<div><b>一点小经验</b><p>${esc(step.tip)}</p></div></div>`:''}<button class="complete-step ${done?'completed':''}" data-action="step-done" aria-pressed="${done}"><span class="checkbox">${done?icon('check',14):''}</span>${done?'这一步已完成':'标记这一步完成'}</button><div class="cook-controls"><button class="button outline" data-action="prev-step" ${c.step===0?'disabled':''}>${icon('back',16)} 上一步</button><button class="button primary" data-action="${c.step===r.steps.length-1?'finish-cook':'next-step'}">${c.step===r.steps.length-1?'做好了，开饭！':'下一步'} ${icon(c.step===r.steps.length-1?'check':'arrow',16)}</button></div><div class="step-dots">${r.steps.map((s,index)=>`<button data-action="jump-step" data-step="${index}" class="${index===c.step?'current':''} ${c.done.includes(index)?'done':''}" aria-label="跳到第${index+1}步">${c.done.includes(index)?'✓':index+1}</button>`).join('')}</div></div></div>`,'cook',true);}
function finishCook(){const r=recipe(state.cook.recipeId);state.cook=null;save();render();detail(r.id,true);toast('开饭啦！把这次的小心得也留下来吧。');setTimeout(()=>$('.notes-section')?.scrollIntoView({behavior:'smooth'}),100);}
function about(){showModal(`${closeButton()}<div class="modal-header"><img class="about-icon" src="assets/icon.svg" alt="Wokzy"><h2>一镬熟，慢慢做好一餐。</h2><p>Wokzy · 个人厨房体验版 v0.1</p></div><div class="padded-form about-content"><p>你可以添加现有食材、找菜谱、调整份数、分步做菜，也可以记下自己的做法和心得。</p><div class="soft-note">${icon('info',20)}<span>数据保存在当前浏览器中。清理浏览器数据会删除记录，不同设备之间暂不自动同步。</span></div><p>网页自动导入和 Bilibili 视频提取会在后续版本中探索；目前可以粘贴文字、手动整理，并保留参考链接。</p><button class="button outline" data-action="export">${icon('download',18)} 导出我的数据备份</button></div>`,'about');}
function feedback(){showModal(`${closeButton()}<div class="modal-header"><span class="tiny-label">MAKE IT YOUR KITCHEN</span><h2>这一版，用起来怎么样？</h2><p>记下不顺手的地方，下一版就有了方向。</p></div><form class="padded-form" id="feedback-form"><label>你的体验与想法<textarea name="feedback" rows="5" placeholder="例如：我想把常用食材放在最上面……" required maxlength="5000"></textarea></label><p class="field-hint">反馈先保存在当前浏览器。保存后可复制到聊天中，供下一轮修改参考。</p><button class="button primary">保存这条反馈</button></form><div class="feedback-history">${state.feedback.slice().reverse().map((f,index)=>`<div class="note"><small>${esc(new Date(f.date).toLocaleDateString('zh-CN'))}</small><p>${esc(f.text)}</p><button class="text-button" data-action="copy-feedback" data-index="${state.feedback.length-1-index}">${icon('copy',14)} 复制反馈</button></div>`).join('')}</div>`,'feedback');}
async function copyText(text){try{await navigator.clipboard.writeText(text);toast('已复制，可以直接粘贴使用。');}catch{showModal(`${closeButton()}<div class="modal-header"><h2>长按或全选，复制清单</h2></div><div class="padded-form"><textarea rows="8" readonly aria-label="待复制的内容">${esc(text)}</textarea></div>`,'copy');$('.modal textarea')?.select();}}
function exportData(){const blob=new Blob([JSON.stringify({app:'wokzy',version:1,exportedAt:new Date().toISOString(),...state},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`wokzy-backup-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('已导出数据备份。');}
function demo(){for(const p of [{name:'番茄',qty:2,unit:'个'},{name:'鸡蛋',qty:4,unit:'个'},{name:'西兰花',qty:300,unit:'克'},{name:'蒜',qty:4,unit:'瓣'},{name:'盐',qty:100,unit:'克',staple:true},{name:'食用油',qty:200,unit:'毫升',staple:true}]){if(!state.pantry.some(x=>canonical(x.name)===p.name))state.pantry.push({...p,staple:!!p.staple});}save();render();toast('示例食材已加入，点开食材可按实际情况修改。');}
function toggleFavorite(id){const index=state.favorites.indexOf(id);if(index<0)state.favorites.push(id);else state.favorites.splice(index,1);save();render();if(modalKind==='detail')detail(activeId,true);toast(index<0?'收藏好了，下次来这里找。':'已取消收藏。');}
function navigate(next){if(next===page){closeModal();return;}location.hash=next;}
window.addEventListener('hashchange',()=>{page=['home','pantry','library','favorites'].includes(location.hash.slice(1))?location.hash.slice(1):'home';query='';filter='all';closeModal();render();window.scrollTo({top:0,behavior:'instant'});});

document.addEventListener('click',event=>{
 const button=event.target.closest('[data-action]');if(!button)return;const a=button.dataset.action,id=button.dataset.id,name=button.dataset.name;
 if(a==='nav')navigate(button.dataset.page);
 else if(a==='close')closeModal();
 else if(a==='detail')detail(id);
 else if(a==='favorite')toggleFavorite(id);
 else if(a==='filter'){filter=button.dataset.filter;document.querySelectorAll('[data-action="filter"]').forEach(b=>{b.classList.toggle('selected',b.dataset.filter===filter);b.setAttribute('aria-pressed',String(b.dataset.filter===filter));});renderCards();}
 else if(a==='reset-filters'){query='';filter='all';render();}
 else if(a==='browse')navigate('library');
 else if(a==='focus-pantry'){$('#pantry-entry')?.scrollIntoView({behavior:'smooth',block:'center'});$('#quick-pantry input')?.focus({preventScroll:true});}
 else if(a==='demo')demo();
 else if(a==='add-stock')stockDialog();
 else if(a==='add-staple')stockDialog('',true);
 else if(a==='edit-stock')stockDialog(name);
 else if(a==='remove-stock'){state.pantry=state.pantry.filter(p=>p.name!==name);save();closeModal();render();toast('已移除这份食材。');}
 else if(a==='toggle-staple'){const p=state.pantry.find(p=>canonical(p.name)===name);if(p)state.pantry=state.pantry.filter(x=>x!==p);else state.pantry.push({name,qty:null,unit:'',staple:true});save();render();}
 else if(a==='new-recipe')editor();
 else if(a==='reference')editor(null,true);
 else if(a==='edit-recipe')editor(id);
 else if(a==='add-row')$('.editor-ingredients').insertAdjacentHTML('beforeend',editorRow());
 else if(a==='remove-row'){if(document.querySelectorAll('.editor-ingredient').length>1)button.closest('.editor-ingredient').remove();else toast('至少保留一种食材。');}
 else if(a==='back-detail')detail(activeId,true);
 else if(a==='serving-plus'){servings=Math.min(20,servings+1);detail(activeId,true);}
 else if(a==='serving-minus'){servings=Math.max(1,servings-1);detail(activeId,true);}
 else if(a==='ingredient-toggle'){const r=recipe(activeId),i=r.ingredients[Number(button.dataset.index)];const p=state.pantry.find(p=>canonical(p.name)===canonical(i.name));if(p)state.pantry=state.pantry.filter(x=>x!==p);else state.pantry.push({name:canonical(i.name),qty:null,unit:'',staple:i.category==='调料'});save();render();detail(activeId,true);}
 else if(a==='copy-shopping')copyText(shoppingText(recipe(activeId),state.pantry,servings));
 else if(a==='start-cook')startCook();
 else if(a==='resume')showCook();
 else if(a==='step-done'){const c=state.cook;const n=c.done.indexOf(c.step);if(n<0)c.done.push(c.step);else c.done.splice(n,1);save();showCook();}
 else if(a==='next-step'){const c=state.cook;if(!c.done.includes(c.step))c.done.push(c.step);c.step=Math.min(recipe(c.recipeId).steps.length-1,c.step+1);save();showCook();}
 else if(a==='prev-step'){state.cook.step=Math.max(0,state.cook.step-1);save();showCook();}
 else if(a==='jump-step'){state.cook.step=Number(button.dataset.step);save();showCook();}
 else if(a==='finish-cook')finishCook();
 else if(a==='about')about();
 else if(a==='export')exportData();
 else if(a==='feedback')feedback();
 else if(a==='copy-feedback')copyText(state.feedback[Number(button.dataset.index)].text);
});
document.addEventListener('input',event=>{if(event.target.id==='recipe-search'){query=event.target.value;renderCards();}});
document.addEventListener('change',event=>{if(event.target.id==='sort-select'){order=event.target.value;renderCards();}});
document.addEventListener('submit',event=>{
 event.preventDefault();const form=event.target,data=new FormData(form);
 if(form.id==='quick-pantry'){const names=String(data.get('name')).split(/[,，、\n]/).map(canonical).filter(Boolean);let added=0;for(const name of names){if(!state.pantry.some(p=>canonical(p.name)===name)){state.pantry.push({name,qty:null,unit:'',staple:false});added++;}}save();render();toast(added?`已添加 ${added} 样食材，推荐已更新。`:'这些食材已经在小仓库里了。');}
 else if(form.id==='stock-form'){const name=canonical(String(data.get('name'))),original=form.dataset.original,qty=data.get('qty'),unit=String(data.get('unit'));if(!name)return;const duplicate=state.pantry.find(p=>canonical(p.name)===name&&p.name!==original);if(duplicate){toast('已有这份食材，请编辑已有记录。');return;}if(qty&&!unit){toast('填了数量后，请选一下单位。');return;}const stock={name,qty:qty?Number(qty):null,unit:qty?unit:'',staple:data.get('staple')==='on'};const index=state.pantry.findIndex(p=>p.name===original);if(index>=0)state.pantry[index]=stock;else state.pantry.push(stock);save();closeModal();render();toast('小仓库更新好了。');}
 else if(form.id==='note-form'){const text=String(data.get('note')).trim();if(!text)return;state.notes.push({id:crypto.randomUUID(),recipeId:activeId,date:new Date().toISOString(),text});save();detail(activeId,true);toast('心得已保存，下一次会更好吃。');}
 else if(form.id==='recipe-form'){
   const ingredients=[...form.querySelectorAll('.editor-ingredient')].map(row=>{const value=f=>row.querySelector(`[data-field="${f}"]`).value.trim();const raw=value('amount'),numeric=/^\d+(\.\d+)?$/.test(raw);return {name:canonical(value('name')),qty:numeric?Number(raw):null,unit:value('unit'),amount:numeric?'':raw,category:value('category'),optional:row.querySelector('[data-field="optional"]').checked};});
   if(ingredients.some(i=>!i.name||(i.qty!==null&&i.qty<=0))){toast('请检查食材名称和用量，数值需要大于零。');return;}
   const steps=String(data.get('steps')).split(/\r?\n/).map(t=>t.trim()).filter(Boolean).map((text,index)=>{const split=text.indexOf('：');return split>0&&split<24?{title:text.slice(0,split),text:text.slice(split+1),tip:''}:{title:`第 ${index+1} 步`,text,tip:''};});
   const name=String(data.get('name')).trim();if(!name||!steps.length){toast('请填写菜名和至少一个步骤。');return;}
   const sourceUrl=String(data.get('sourceUrl')).trim();if(sourceUrl&&!safeUrl(sourceUrl)){toast('参考链接需以 https:// 或 http:// 开头。');return;}
   const old=recipe(form.dataset.id);const r={...old,id:old?.id||crypto.randomUUID(),name,subtitle:String(data.get('subtitle')).trim(),servings:Number(data.get('servings')),minutes:Number(data.get('minutes')),difficulty:String(data.get('difficulty')),tools:String(data.get('tools')).trim(),tags:String(data.get('tags')).split(/[,，、]/).map(t=>t.trim()).filter(Boolean),tag:old?.tag||'我的私房菜',sourceType:String(data.get('sourceType')),sourceUrl,ingredients,steps,originalSourceType:old?.originalSourceType||old?.sourceType||null,editedAt:new Date().toISOString()};
   if(old)state.recipes[state.recipes.indexOf(old)]=r;else state.recipes.unshift(r);
   if(state.cook?.recipeId===r.id){state.cook.step=0;state.cook.done=[];}
   save();render();detail(r.id);toast('菜谱保存好了，也会加入食材推荐。');
 }
 else if(form.id==='feedback-form'){const text=String(data.get('feedback')).trim();if(!text)return;state.feedback.push({text,date:new Date().toISOString()});save();feedback();toast('反馈记好了，可以复制到聊天里。');}
});
document.addEventListener('keydown',event=>{if(!modalKind)return;if(event.key==='Escape'){closeModal();return;}if(event.key==='Tab'){const focusable=[...document.querySelectorAll('.modal button:not([disabled]),.modal a,.modal input,.modal textarea,.modal select')].filter(e=>e.offsetParent!==null);const first=focusable[0],last=focusable.at(-1);if(!first){event.preventDefault();return;}if(event.shiftKey&&(document.activeElement===first||document.activeElement===$('.modal'))){last.focus();event.preventDefault();}else if(!event.shiftKey&&(document.activeElement===last||document.activeElement===$('.modal'))){first.focus();event.preventDefault();}}});
save();render();
